const PAGE_TYPES = new Map([['catalog', 'catalog'], ['checkout', 'checkout']]);
export function onRoute(pathname) {
  const key = pathname.split('/').filter(Boolean)[0] || 'catalog';
  const pageType = PAGE_TYPES.get(key) || 'other';
  rum.setGlobalAttributes({ 'page.type': pageType, 'sample.bt': pageType });
  tracer.startSpan('route.change', { attributes: { 'page.type': pageType } }).end();
}

