export function publish(message) {
  propagation.inject(context.active(), message.attributes, messageSetter);
  return bus.send(message);
}
export function consume(record) {
  const extracted = propagation.extract(context.active(), record.attributes, messageGetter);
  return context.with(extracted, () => processOrder(record));
}
export function redrive(record) {
  const original = propagation.extract(context.active(), record.originalTrace, messageGetter);
  const link = { context: trace.getSpanContext(original), attributes: { 'messaging.operation': 'redrive' } };
  return tracer.startActiveSpan('order.dlq.redrive', { links: [link] }, span => processRedrive(record).finally(() => span.end()));
}

