export function captureAttribution(url, referrer) {
  const medium = url.searchParams.get('utm_medium') || '';
  const source = medium === 'cpc' ? 'paid-search' : referrer ? 'referral' : 'direct';
  const value = { source, medium: medium || 'none', attributed: source !== 'direct' };
  const firstKey = 'sample.attribution.first';
  if (!localStorage.getItem(firstKey)) localStorage.setItem(firstKey, JSON.stringify(value));
  sessionStorage.setItem('sample.attribution.last', JSON.stringify(value));
  addActiveSpanEvent('session.ad-attribution', value);
  setBoundedAttributionBaggage(value);
}
